function fibonacci(n) {
  if (n == 0 || n == 1) {
    return n;
  }

  let fibo = [0, 1];

  for (let i = 2; i <= n; i++) {
    let nextFibonacci = fibo[i - 1] + fibo[i - 2];
    fibo.push(nextFibonacci);
  }

  return fibo[n];
}

def longest_consecutive(numbers):
    longest_sequence = 0
    numbers_set = set(numbers)

    for num in numbers:
        if num - 1 not in numbers_set:
            current_number = num
            current_sequence = 1

            while current_number + 1 in numbers_set:
                current_sequence += 1
                current_number += 1

            longest_sequence = max(longest_sequence, current_sequence)

    return longest_sequence

